#include <string.h>
#include <openssl/md5.h>

// Forward declaration of the PgSocket structure
typedef struct PgSocket PgSocket;

// Assume the structure contains the following fields:
// - char *stored_password
// - char *auth_type

bool verify_password(PgSocket *client, const char *passwd) {
    // Check if client or password is NULL
    if (!client || !passwd) {
        return false;
    }

    // Check if stored password or provided password is empty
    if (!client->stored_password || strlen(client->stored_password) == 0 ||
        strlen(passwd) == 0) {
        return false;
    }

    // Check authentication type
    if (strcmp(client->auth_type, "plain") == 0) {
        // Plain text comparison
        return strcmp(client->stored_password, passwd) == 0;
    } else if (strcmp(client->auth_type, "crypt") == 0) {
        // Crypt comparison
        // This is a simplified example - in practice you would use crypt()
        // and compare the results
        return strcmp(client->stored_password, crypt(passwd, client->stored_password)) == 0;
    } else if (strcmp(client->auth_type, "MD5") == 0) {
        // MD5 comparison
        if (strlen(passwd) == 0) {
            return false;
        }

        // Check if stored password is in the format "MD5<hash>"
        if (strncmp(client->stored_password, "MD5", 3) != 0) {
            return false;
        }

        // Extract the hash from the stored password
        char *stored_hash = client->stored_password + 3;

        // Generate MD5 hash of the password
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)passwd, strlen(passwd), md5_hash);

        // Convert the hash to a hexadecimal string
        char generated_hash[2 * MD5_DIGEST_LENGTH + 1];
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            sprintf(generated_hash + 2 * i, "%02x", md5_hash[i]);
        }

        // Compare the generated hash with the stored hash
        return strcmp(stored_hash, generated_hash) == 0;
    }

    // If none of the authentication types match
    return false;
}
